<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({ upcoming: { type: Array, default: () => [] }, rows: { type: Array, default: () => [] }, days: { type: Number, default: 120 }, unread: { type: Number, default: 0 }, canCreate: Boolean, canEdit: Boolean, canDelete: Boolean, safeAreaStyle: { type: Object, default: () => ({}) } }); const emit = defineEmits(['back', 'create', 'notifications', 'edit', 'delete']); function countdown(row) { return row.daysUntil === 0 ? 'Hôm nay' : row.daysUntil === 1 ? '1 ngày' : row.daysUntil == null ? '—' : `${row.daysUntil} ngày`; } function exportIcs(row) { if (Number.isInteger(Number(row?.id)) && Number(row.id) > 0) window.location.assign(`/api/reminders/${Number(row.id)}/ics`); }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Lịch nhắc" @back="emit('back')"><template #actions><MButton variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('notifications')">Tin<span v-if="unread"> {{ unread }}</span></MButton><MButton v-if="canCreate" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('create')">Thêm</MButton></template></MMobileTopBar><div class="min-h-0 flex-1 overflow-y-auto"><section class="border-b border-[var(--mds-border-light)]"><header class="mds-mobile-gutter-x py-3"><h2 class="text-[16px] font-semibold">Sắp diễn ra</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Trong {{ days }} ngày tới</p></header><div v-if="upcoming.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="row in upcoming" :key="row.id" class="mds-mobile-gutter-x py-3"><div class="flex items-start justify-between gap-3"><strong class="min-w-0 text-[14px] leading-5">{{ row.title }}</strong><MTag :color="row.daysUntil != null && row.daysUntil <= row.leadDays ? 'warning' : 'neutral'">{{ countdown(row) }}</MTag></div><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.occurDate }}<span v-if="row.subjectName"> · {{ row.subjectName }}</span></p></article></div><MEmptyState v-else title="Chưa có lịch sắp diễn ra" description="Mốc cần chăm sóc sẽ xuất hiện ở đây." /></section><section><header class="mds-mobile-gutter-x border-b border-[var(--mds-border-light)] py-3"><h2 class="text-[16px] font-semibold">Tất cả ngày nhắc</h2></header><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="row in rows" :key="row.id" class="mds-mobile-gutter-x py-3"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><strong class="block text-[14px] leading-5">{{ row.title }}</strong><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.eventDate }} · {{ row.recurring ? 'Hằng năm' : 'Một lần' }}</p></div><MTag color="neutral">{{ row.dateTypeLabel }}</MTag></div><p v-if="row.subjectName" class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">{{ row.subjectName }}</p><p v-if="row.note" class="mt-1 text-[13px] leading-[18px]">{{ row.note }}</p><div class="mt-2 flex justify-end gap-3"><MButton variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="exportIcs(row)">.ics</MButton><MButton v-if="canEdit" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('edit', row)">Sửa</MButton><MButton v-if="canDelete" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)] text-[var(--mds-danger)]" @click="emit('delete', row)">Xóa</MButton></div></article></div><MEmptyState v-else title="Chưa có ngày nhắc" description="Thêm lịch khi cần theo dõi một mốc chăm sóc." /></section></div></section></template>
